<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\CouncilResultIdentityService;
Auth::requirePermission('competitors.edit');$pdo=Database::connection();$id=(int)($_GET['id']??$_POST['id']??0);$row=null;$error='';
if($id){$s=$pdo->prepare('SELECT * FROM bdc_wdc_identities WHERE id=:id');$s->execute(['id'=>$id]);$row=$s->fetch();if(!$row){http_response_code(404);exit('WDC competitor not found.');}}
if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid security token.');$name=trim((string)($_POST['display_name']??''));$type=(string)($_POST['entry_type']??'solo');$country=trim((string)($_POST['country']??''));$photo=trim((string)($_POST['photo_url']??''));$status=(string)($_POST['status']??'active');if($name==='')throw new RuntimeException('Name is required.');if(!in_array($type,['solo','couple','duo','pro_am','team'],true))throw new RuntimeException('Invalid entry type.');if(!in_array($status,['active','archived'],true))throw new RuntimeException('Invalid status.');if($id){$protected=$pdo->prepare("SELECT (SELECT COUNT(*) FROM bdc_dance_cup_result_history WHERE wdc_identity_id=:a)+(SELECT COUNT(*) FROM bdc_wdc_championship_points WHERE wdc_identity_id=:b)");$protected->execute(['a'=>$id,'b'=>$id]);if($status==='archived'&&(int)$protected->fetchColumn()>0)throw new RuntimeException('Official Dance Cup history protects this WDC identity from archival.');$normal=function_exists('mb_strtolower')?mb_strtolower($name,'UTF-8'):strtolower($name);$normal=trim((string)preg_replace('/[^\pL\pN]+/u',' ',$normal));$pdo->prepare("UPDATE bdc_wdc_identities SET display_name=:name,normalised_name=:normal,country=NULLIF(:country,''),photo_url=NULLIF(:photo,''),status=:status WHERE id=:id")->execute(['name'=>$name,'normal'=>$normal,'country'=>$country,'photo'=>$photo,'status'=>$status,'id'=>$id]);Auth::audit((int)(Auth::user()['id']??0),'wdc_identity_updated',[],'wdc_identity',$id);}else{$identity=CouncilResultIdentityService::wdcIdentityForEntry($pdo,$type,$name,null);$id=(int)$identity['id'];$pdo->prepare("UPDATE bdc_wdc_identities SET country=NULLIF(:country,''),photo_url=NULLIF(:photo,''),status=:status WHERE id=:id")->execute(['country'=>$country,'photo'=>$photo,'status'=>$status,'id'=>$id]);}header('Location: competitors.php#wdc-'.$id,true,303);exit;}catch(Throwable $e){$error=$e->getMessage();}}
$registrations=[];$history=[];$points=[];if($id){$s=$pdo->prepare('SELECT * FROM bdc_wdc_registrations WHERE wdc_identity_id=:id ORDER BY event_name,category_name');$s->execute(['id'=>$id]);$registrations=$s->fetchAll();$s=$pdo->prepare('SELECT event_name,category_name,placement,approved_at FROM bdc_dance_cup_result_history WHERE wdc_identity_id=:id ORDER BY approved_at DESC');$s->execute(['id'=>$id]);$history=$s->fetchAll();$s=$pdo->prepare('SELECT division,placement,points,awarded_at FROM bdc_wdc_championship_points WHERE wdc_identity_id=:id ORDER BY awarded_at DESC');$s->execute(['id'=>$id]);$points=$s->fetchAll();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$id?'Edit':'Add'?> Dance Cup Competitor</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4" style="max-width:900px"><div class="d-flex justify-content-between mb-3"><h1 class="h3"><?=$id?'Edit':'Add'?> Dance Cup Competitor</h1><a class="btn btn-outline-dark" href="competitors.php<?=$id?'#wdc-'.$id:''?>">Back</a></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post" class="card border-0 shadow-sm"><div class="card-body row g-3"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="id" value="<?=$id?>"><?php if($row):?><div class="col-12"><label class="form-label">WDC ID</label><input class="form-control" value="<?=e($row['identity_code'])?>" readonly><div class="form-text">Permanent and cannot be changed.</div></div><?php endif;?><div class="col-md-8"><label class="form-label">Competitor, couple or team name</label><input class="form-control" name="display_name" value="<?=e($row['display_name']??'')?>" required></div><div class="col-md-4"><label class="form-label">Entry type</label><select class="form-select" name="entry_type" <?=$row?'disabled':''?>><?php foreach(['solo','couple','duo','pro_am','team'] as $v):?><option value="<?=$v?>" <?=($row['entry_type']??'solo')===$v?'selected':''?>><?=e(ucwords(str_replace('_',' ',$v)))?></option><?php endforeach;?></select><?php if($row):?><input type="hidden" name="entry_type" value="<?=e($row['entry_type'])?>"><?php endif;?></div><div class="col-md-6"><label class="form-label">Country</label><input class="form-control" name="country" value="<?=e($row['country']??'')?>"></div><div class="col-md-6"><label class="form-label">Status</label><select class="form-select" name="status"><option value="active" <?=($row['status']??'active')==='active'?'selected':''?>>Active</option><option value="archived" <?=($row['status']??'')==='archived'?'selected':''?>>Archived</option></select></div><div class="col-12"><label class="form-label">Photo URL</label><input class="form-control" name="photo_url" value="<?=e($row['photo_url']??'')?>"></div><?php if($id):?><div class="col-12"><a class="btn btn-outline-primary" href="photo-adjust.php?id=<?=$id?>">Upload or adjust photo</a></div><?php endif;?></div><div class="card-footer bg-white text-end"><button class="btn btn-primary">Save Competitor</button></div></form>
<?php if($id):?><section class="card border-0 shadow-sm mt-4"><div class="card-body"><h2 class="h5">Registrations</h2><?php foreach($registrations as $r):?><div class="border rounded p-2 mb-2"><strong><?=e($r['category_name'])?></strong> · <?=e($r['event_name'])?> · <?=e(ucwords($r['dance_style']))?> · <?=e(ucwords(str_replace('_',' ',$r['competition_level'])))?> <span class="badge text-bg-<?=$r['status']==='registered'?'success':'secondary'?>"><?=e($r['status'])?></span></div><?php endforeach;?><?php if(!$registrations):?><p class="text-muted mb-0">No registrations.</p><?php endif;?></div></section><section class="card border-0 shadow-sm mt-4"><div class="card-body"><h2 class="h5">Official history and championship points</h2><?php foreach($history as $h):?><div class="border-bottom py-2"><strong><?=e($h['event_name'])?> · <?=e($h['category_name'])?></strong><span class="float-end">Place <?=e((string)$h['placement'])?></span></div><?php endforeach;?><?php foreach($points as $p):?><div class="border-bottom py-2">Championship <?=e(ucwords($p['division']))?><span class="float-end"><?=e((string)(float)$p['points'])?> points</span></div><?php endforeach;?><?php if(!$history&&!$points):?><p class="text-muted mb-0">No published result or championship points.</p><?php endif;?></div></section><?php endif;?></main></body></html>
